modify replace value of node $c/@b with attribute b { 'a' }
return $c

copy $c := <a b=""/>
modify replace value of node $c/@b with text { 'a' }
return $c

copy $c := <a b=""/>
modify replace value of node $c/@b with comment { 'a' }
return $c

copy $c := <a b=""/>
modify replace value of node $c/@b with processing-instruction x { 'a' }
return $c

copy $c := <a b=""/>
modify replace value of node $c/@b with document { 'a' }
return $c

copy $c := <a b=""/>
modify replace value of node $c/@b with element x { 'a' }
return $c

copy $c := text { 'A' }
modify replace value of node $c with 'B'
return $c

copy $c := document { 'A' }
modify replace value of node $c/text() with 'B'
return string($c)

copy $c := attribute a { 'A' }
modify replace value of node $c with 'B'
